    color: #95600b;
}

/* Final total */

.aj-checkout-final-total {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 10px;
    padding: 15px;
    background: #f1f8f3;
    border-radius: 12px;
}

.aj-checkout-final-total &gt; div {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.aj-checkout-final-total &gt; div strong {
    font-size: 15px;
    color: #172033;
}

.aj-checkout-final-total small {
    font-size: 10px;
    color: #87909e;
}

.aj-checkout-final-total &gt; strong {
